package tmmodern;
import net.minecraft.world.*;import net.minecraft.world.item.*;import net.minecraft.world.item.context.UseOnContext;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.core.*;import net.minecraft.network.chat.Component;
public class DisassemblerItem extends Item {
    public DisassemblerItem(){super(new Properties().stacksTo(1).rarity(Rarity.UNCOMMON));}
    public static int charge(ItemStack s){return s.hasTag()?Math.max(0,Math.min(50000,s.getTag().getInt("charge"))):0;}public static int mode(ItemStack s){return s.hasTag()?Math.floorMod(s.getTag().getInt("mode"),4):0;}public static int efficiency(int m){return new int[]{20,8,128,0}[Math.floorMod(m,4)];}
    public static void consume(ItemStack s,int n){s.getOrCreateTag().putInt("charge",Math.max(0,charge(s)-n));}
    @Override public boolean canPerformAction(ItemStack stack,net.minecraftforge.common.ToolAction action){return action==net.minecraftforge.common.ToolActions.HOE_TILL;}
    @Override public boolean isBarVisible(ItemStack s){return true;}@Override public int getBarWidth(ItemStack s){return Math.round(13f*charge(s)/50000);}@Override public int getBarColor(ItemStack s){return 0x444444;}
    @Override public float getDestroySpeed(ItemStack s,BlockState state){return charge(s)>0?efficiency(mode(s)):1;}@Override public boolean isCorrectToolForDrops(ItemStack s,BlockState state){return !state.is(Blocks.BEDROCK);}
    @Override public boolean mineBlock(ItemStack s,Level l,BlockState state,BlockPos pos,LivingEntity owner){if(state.getDestroySpeed(l,pos)!=0)consume(s,(int)(5*efficiency(mode(s))/8.0));return true;}
    @Override public boolean hurtEnemy(ItemStack s,LivingEntity target,LivingEntity owner){consume(s,50);return true;}
    @Override public com.google.common.collect.Multimap<net.minecraft.world.entity.ai.attributes.Attribute,net.minecraft.world.entity.ai.attributes.AttributeModifier> getAttributeModifiers(EquipmentSlot slot,ItemStack s){var out=com.google.common.collect.HashMultimap.<net.minecraft.world.entity.ai.attributes.Attribute,net.minecraft.world.entity.ai.attributes.AttributeModifier>create();if(slot==EquipmentSlot.MAINHAND)out.put(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE,new net.minecraft.world.entity.ai.attributes.AttributeModifier(BASE_ATTACK_DAMAGE_UUID,"Disassembler damage",charge(s)>0?19:3,net.minecraft.world.entity.ai.attributes.AttributeModifier.Operation.ADDITION));return out;}
    @Override public InteractionResultHolder<ItemStack> use(Level l,Player p,InteractionHand h){var s=p.getItemInHand(h);if(p.isShiftKeyDown()){s.getOrCreateTag().putInt("mode",(mode(s)+1)%4);p.displayClientMessage(Component.translatable("text.disassembler."+new String[]{"normal","slow","fast","off"}[mode(s)]),true);return InteractionResultHolder.success(s);}return InteractionResultHolder.pass(s);}
    @Override public InteractionResult useOn(UseOnContext c){var p=c.getPlayer();if(p==null||p.isShiftKeyDown()||mode(c.getItemInHand())==3||c.getClickedFace()==Direction.DOWN)return InteractionResult.PASS;var center=c.getLevel().getBlockState(c.getClickedPos());if(!center.is(Blocks.DIRT)&&!center.is(Blocks.GRASS_BLOCK)&&!center.is(Blocks.FARMLAND))return InteractionResult.PASS;int radius=mode(c.getItemInHand())==1?0:mode(c.getItemInHand())==2?2:1;boolean changed=false;for(var pos:BlockPos.betweenClosed(c.getClickedPos().offset(-radius,0,-radius),c.getClickedPos().offset(radius,0,radius))){var l=c.getLevel();if(!l.mayInteract(p,pos)||!l.isEmptyBlock(pos.above())||!p.isCreative()&&charge(c.getItemInHand())<25)continue;var state=l.getBlockState(pos);if(!state.is(Blocks.DIRT)&&!state.is(Blocks.GRASS_BLOCK))continue;var hoeContext=new UseOnContext(p,c.getHand(),new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(pos),Direction.UP,pos,false));var modified=state.getToolModifiedState(hoeContext,net.minecraftforge.common.ToolActions.HOE_TILL,false);if(modified==null)continue;if(!l.isClientSide){l.setBlock(pos,modified,3);if(!p.isCreative())consume(c.getItemInHand(),25);}changed=true;}return changed?InteractionResult.SUCCESS:InteractionResult.PASS;}
    @Override public void inventoryTick(ItemStack s,Level l,Entity owner,int slot,boolean held){if(!l.isClientSide&&owner instanceof Player p&&owner.tickCount%20==0){int amount=Math.min(100,50000-charge(s));if(amount>0&&tc4revival.content.WandInventory.consume(p,java.util.Map.of(MagicFocus.aspect("perditio"),amount)))s.getOrCreateTag().putInt("charge",charge(s)+amount);}}
    @Override public void appendHoverText(ItemStack s,Level l,java.util.List<Component> out,TooltipFlag flag){out.add(Component.translatable("text.disassembler.charge").append(": "+charge(s)/100+"/500"));out.add(Component.translatable("text.disassembler."+new String[]{"normal","slow","fast","off"}[mode(s)]));out.add(Component.translatable("text.disassembler.efficiency").append(": "+efficiency(mode(s))));}
}
